+#!/usr/bin/env node
+import { readFileSync } from "node:fs";
+import path from "node:path";
+import { parseTasks } from "./tasks.ts";
+import { planOrder } from "./planner.ts";
+import { TaskPlanError } from "./errors.ts";
+
+const USAGE = "Usage: node src/cli.ts plan <file.json> [--json]";
+
+function printUsageAndExit(): never {
+  process.stderr.write(USAGE + "\n");
+  process.exit(2);
+}
+
+function main(): void {
+  const argv = process.argv.slice(2);
+
+  if (argv.length === 0) {
+    process.stderr.write(USAGE + "\n");
+    process.exit(2);
+  }
+
+  const command = argv[0];
+  if (command !== "plan") {
+    process.stderr.write(USAGE + "\n");
+    process.exit(2);
+  }
+
+  const rest = argv.slice(1);
+
+  let jsonFlag = false;
+  let jsonCount = 0;
+  let fileArg: string | undefined = undefined;
+
+  for (const arg of rest) {
+    if (arg === "--json") {
+      jsonCount++;
+      if (jsonCount > 1) {
+        process.stderr.write(USAGE + "\n");
+        process.exit(2);
+      }
+      jsonFlag = true;
+    } else if (arg.startsWith("-")) {
+      // unknown option
+      process.stderr.write(USAGE + "\n");
+      process.exit(2);
+    } else {
+      if (fileArg === undefined) {
+        fileArg = arg;
+      } else {
+        // extra argument
+        process.stderr.write(USAGE + "\n");
+        process.exit(2);
+      }
+    }
+  }
+
+  if (fileArg === undefined) {
+    process.stderr.write(USAGE + "\n");
+    process.exit(2);
+  }
+
+  // Read file (or STDIN if "-")
+  let raw: string;
+  try {
+    if (fileArg === "-") {
+      raw = readFileSync(0, "utf8");
+    } else {
+      const resolved = path.resolve(process.cwd(), fileArg);
+      raw = readFileSync(resolved, "utf8");
+    }
+  } catch (e) {
+    const err = e as NodeJS.ErrnoException;
+    const reason = err.message ?? String(e);
+    process.stderr.write(`error: ${reason}\n`);
+    process.stderr.write(USAGE + "\n");
+    process.exit(2);
+  }
+
+  // Parse JSON
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(raw!);
+  } catch (e) {
+    const err = e as Error;
+    process.stderr.write(`error INVALID_JSON: ${err.message}\n`);
+    process.exit(1);
+  }
+
+  // Parse tasks and plan
+  try {
+    const tasks = parseTasks(parsed);
+    const result = planOrder(tasks);
+
+    if (jsonFlag) {
+      const out = JSON.stringify({ order: result.order, stages: result.stages });
+      process.stdout.write(out + "\n");
+    } else {
+      let out = "";
+      if (result.stages.length === 0) {
+        out = "Order:\n";
+      } else {
+        for (let i = 0; i < result.stages.length; i++) {
+          const stage = result.stages[i]!;
+          out += `Stage ${i + 1}: ${stage.join(", ")}\n`;
+        }
+        out += `Order: ${result.order.join(", ")}\n`;
+      }
+      process.stdout.write(out);
+    }
+    process.exit(0);
+  } catch (e) {
+    if (e instanceof TaskPlanError) {
+      process.stderr.write(`error ${e.code}: ${e.message}\n`);
+      process.exit(1);
+    }
+    // Re-throw unexpected errors
+    throw e;
+  }
+}
+
+main();
