+/** Two or more tasks share the same id. */
+export class DuplicateTaskError extends TaskPlanError {
+  /** Every id that occurs more than once, each once, ordered by first position. */
+  readonly taskIds: string[];
+
+  constructor(taskIds: string[], message?: string) {
+    super("DUPLICATE_ID", message ?? `duplicate task ids: ${taskIds.join(", ")}`);
+    this.taskIds = [...taskIds];
+  }
+}
+
+/** A task depends on an id that does not exist. */
+export class UnknownDependencyError extends TaskPlanError {
+  /** The task that has the missing dependency. */
+  readonly taskId: string;
+  /** The missing dependency id. */
+  readonly dependency: string;
+
+  constructor(taskId: string, dependency: string, message?: string) {
+    super("UNKNOWN_DEPENDENCY", message ?? `task "${taskId}" depends on unknown "${dependency}"`);
+    this.taskId = taskId;
+    this.dependency = dependency;
+  }
+}
+
+/** The dependency graph contains a cycle. */
+export class CycleError extends TaskPlanError {
+  /** Closed path: first and last ids are equal, each id depends on the next. */
+  readonly cycle: string[];
+
+  constructor(cycle: string[], message?: string) {
+    super("CYCLE", message ?? `cycle detected: ${cycle.join(" -> ")}`);
+    this.cycle = [...cycle];
+  }
+}
