+import { CycleError, DuplicateTaskError, UnknownDependencyError } from "./errors.ts";
+import type { TaskSpec } from "./tasks.ts";
+
+/** Result of {@link planOrder}. */
+export interface PlanResult {
+  /** Every task id in execution order, respecting dependencies. */
+  order: string[];
+  /** Stages grouped by earliest possible round. */
+  stages: string[][];
+}
+
+/**
+ * Plans execution order and stages for the given tasks.
+ *
+ * Order is built one task at a time; among ready tasks the highest priority
+ * wins, with input order as tie-breaker. Stages are computed from the
+ * longest dependency chain.
+ *
+ * @throws DuplicateTaskError when ids are not unique
+ * @throws UnknownDependencyError when a dependency is missing
+ * @throws CycleError when the graph has a cycle
+ */
+export function planOrder(tasks: TaskSpec[]): PlanResult {
+  const n = tasks.length;
+  if (n === 0) return { order: [], stages: [] };
+
+  // R3.1 duplicates
+  {
+    const count = new Map<string, number>();
+    const firstPos = new Map<string, number>();
+    for (let i = 0; i < n; i++) {
+      const t = tasks[i]!;
+      const id = t.id;
+      const cur = count.get(id);
+      count.set(id, (cur !== undefined ? cur : 0) + 1);
+      if (!firstPos.has(id)) firstPos.set(id, i);
+    }
+    const dupIds: string[] = [];
+    for (const [id, c] of count) {
+      if (c > 1) dupIds.push(id);
+    }
+    if (dupIds.length > 0) {
+      dupIds.sort((a, b) => {
+        const pa = firstPos.get(a);
+        const pb = firstPos.get(b);
+        return (pa !== undefined ? pa : 0) - (pb !== undefined ? pb : 0);
+      });
+      throw new DuplicateTaskError(dupIds);
+    }
+  }
+
+  // Build id -> index map
+  const idToIndex = new Map<string, number>();
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    idToIndex.set(t.id, i);
+  }
+
+  // R3.2 unknown dependency (earliest task, earliest dependsOn entry)
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    const deps = t.dependsOn;
+    for (let j = 0; j < deps.length; j++) {
+      const dep = deps[j]!;
+      if (!idToIndex.has(dep)) {
+        throw new UnknownDependencyError(t.id, dep);
+      }
+    }
+  }
+
+  // Build deduped dependencies per task and adjacency / indegree
+  const uniqueDeps: number[][] = new Array(n);
+  const adj: number[][] = new Array(n);
+  const indegree = new Array<number>(n).fill(0);
+  for (let i = 0; i < n; i++) adj[i] = [];
+
+  for (let i = 0; i < n; i++) {
+    const t = tasks[i]!;
+    const deps = t.dependsOn;
+    const seen = new Set<string>();
+    const list: number[] = [];
+    for (let j = 0; j < deps.length; j++) {
+      const depId = deps[j]!;
+      if (seen.has(depId)) continue;
+      seen.add(depId);
+      const depIdx = idToIndex.get(depId);
+      if (depIdx === undefined) continue; // already checked, but guard
+      list.push(depIdx);
+    }
+    uniqueDeps[i] = list;
+    indegree[i] = list.length;
+    for (let k = 0; k < list.length; k++) {
+      const depIdx = list[k]!;
+      const bucket = adj[depIdx];
+      if (bucket !== undefined) bucket.push(i);
+    }
+  }
+
+  // Kahn layering + priority selection for order
+  const heap: number[] = [];
+
+  function higher(a: number, b: number): boolean {
+    const ta = tasks[a]!;
+    const tb = tasks[b]!;
+    const pa = ta.priority;
+    const pb = tb.priority;
+    if (pa !== pb) return pa > pb;
+    return a < b;
+  }
+
+  function heapPush(v: number): void {
+    heap.push(v);
+    let i = heap.length - 1;
+    while (i > 0) {
+      const p = (i - 1) >> 1;
+      const hi = heap[i];
+      const hp = heap[p];
+      if (hi === undefined || hp === undefined) break;
+      if (higher(hi, hp)) {
+        heap[i] = hp;
+        heap[p] = hi;
+        i = p;
+      } else break;
+    }
+  }
+
+  function heapPop(): number | undefined {
+    if (heap.length === 0) return undefined;
+    const top = heap[0]!;
+    const last = heap.pop()!;
+    if (heap.length > 0) {
+      heap[0] = last;
+      let i = 0;
+      while (true) {
+        const l = i * 2 + 1;
+        const r = l + 1;
+        let best = i;
+        const hBest = heap[best];
+        if (hBest === undefined) break;
+        if (l < heap.length) {
+          const hl = heap[l]!;
+          if (higher(hl, hBest)) best = l;
+        }
+        if (r < heap.length) {
+          const hr = heap[r]!;
+          const hb = heap[best]!;
+          if (higher(hr, hb)) best = r;
+        }
+        if (best !== i) {
+          const tmp = heap[i]!;
+          heap[i] = heap[best]!;
+          heap[best] = tmp;
+          i = best;
+        } else break;
+      }
+    }
+    return top;
+  }
+
+  for (let i = 0; i < n; i++) {
+    const d = indegree[i];
+    if (d !== undefined && d === 0) heapPush(i);
+  }
+
+  const orderIdx: number[] = [];
+  const stageLevel = new Array<number>(n).fill(0);
+
+  while (heap.length > 0) {
+    const u = heapPop()!;
+    orderIdx.push(u);
+    const lu = stageLevel[u]!;
+    const nextLevel = lu + 1;
+    const dependents = adj[u];
+    if (dependents === undefined) continue;
+    for (let k = 0; k < dependents.length; k++) {
+      const v = dependents[k]!;
+      const lv = stageLevel[v]!;
+      if (lv < nextLevel) stageLevel[v] = nextLevel;
+      const dv = indegree[v]!;
+      indegree[v] = dv - 1;
+      if (indegree[v] === 0) heapPush(v);
+    }
+  }
+
+  if (orderIdx.length !== n) {
+    const color = new Array<number>(n).fill(0);
+    type Frame = { v: number; idx: number };
+    for (let start = 0; start < n; start++) {
+      if (color[start] !== 0) continue;
+      const stack: Frame[] = [{ v: start, idx: 0 }];
+      color[start] = 1;
+      while (stack.length > 0) {
+        const frame = stack[stack.length - 1]!;
+        const v = frame.v;
+        const deps = uniqueDeps[v];
+        if (deps === undefined) {
+          color[v] = 2;
+          stack.pop();
+          continue;
+        }
+        if (frame.idx < deps.length) {
+          const w = deps[frame.idx]!;
+          frame.idx++;
+          const cw = color[w]!;
+          if (cw === 0) {
+            color[w] = 1;
+            stack.push({ v: w, idx: 0 });
+          } else if (cw === 1) {
+            let pos = -1;
+            for (let i = 0; i < stack.length; i++) {
+              if (stack[i]!.v === w) { pos = i; break; }
+            }
+            const cycleIdx: number[] = [];
+            if (pos !== -1) {
+              for (let i = pos; i < stack.length; i++) cycleIdx.push(stack[i]!.v);
+            }
+            cycleIdx.push(w);
+            const cycle = cycleIdx.map((idx) => tasks[idx]!.id);
+            throw new CycleError(cycle);
+          }
+        } else {
+          color[v] = 2;
+          stack.pop();
+        }
+      }
+    }
+    throw new CycleError([]);
+  }
+
+  const order = orderIdx.map((i) => tasks[i]!.id);
+
+  let maxStage = 0;
+  for (let i = 0; i < n; i++) {
+    const lv = stageLevel[i]!;
+    if (lv > maxStage) maxStage = lv;
+  }
+  const stagesBuckets: number[][] = new Array(maxStage + 1);
+  for (let i = 0; i <= maxStage; i++) stagesBuckets[i] = [];
+  for (let i = 0; i < n; i++) {
+    const lv = stageLevel[i]!;
+    const bucket = stagesBuckets[lv]!;
+    bucket.push(i);
+  }
+  const stages: string[][] = [];
+  for (let k = 0; k < stagesBuckets.length; k++) {
+    const bucket = stagesBuckets[k]!;
+    bucket.sort((a, b) => {
+      const pa = tasks[a]!.priority;
+      const pb = tasks[b]!.priority;
+      if (pa !== pb) return pb - pa;
+      return a - b;
+    });
+    stages.push(bucket.map((idx) => tasks[idx]!.id));
+  }
+
+  return { order, stages };
+}
